// shared/pipes/relative-time.pipe.ts
import { Pipe, PipeTransform, OnDestroy, ChangeDetectorRef } from '@angular/core';
import { Subscription, interval } from 'rxjs';

@Pipe({
  name: 'relativeTime',
  pure: false // Para actualización automática
})
export class RelativeTimePipe implements PipeTransform, OnDestroy {
  private timerSubscription?: Subscription;
  private lastTimestamp: string = '';
  private lastResult: string = '';

  constructor(private cdr: ChangeDetectorRef) {}

  transform(timestamp: string): string {
    if (this.lastTimestamp !== timestamp) {
      this.lastTimestamp = timestamp;
      this.updateResult(timestamp);
      this.startTimer();
    }
    return this.lastResult;
  }

  private updateResult(timestamp: string): void {
    const date = new Date(timestamp);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) this.lastResult = 'Ahora';
    else if (diffMins < 60) this.lastResult = `Hace ${diffMins} min`;
    else if (diffHours < 24) this.lastResult = `Hace ${diffHours} h`;
    else if (diffDays < 7) this.lastResult = `Hace ${diffDays} d`;
    else this.lastResult = date.toLocaleDateString();
  }

  private startTimer(): void {
    this.timerSubscription?.unsubscribe();
    this.timerSubscription = interval(60000).subscribe(() => {
      this.updateResult(this.lastTimestamp);
      this.cdr.markForCheck();
    });
  }

  ngOnDestroy(): void {
    this.timerSubscription?.unsubscribe();
  }
}
