import { RouterOutlet } from '@angular/router';
import { ToastModule } from 'primeng/toast';
import { LoadingComponent } from './shared/components/loading/loading.component';
import { SessionTimeoutModalComponent } from './core/components/session-timeout/session-timeout-modal.component';
import { OtpCodeComponent } from './shared/components/otp-code/otp-code.component';
import { CodigoMaestroModalComponent } from './shared/components/otp-code/codigo-maestro-modal.component';
import { NotificationService } from './core/services/notification/notification.service';
import { AuthService } from './core/services/auth.service';
import { Router, NavigationEnd, NavigationStart, NavigationCancel, NavigationError, RouteConfigLoadStart, RouteConfigLoadEnd, RoutesRecognized } from '@angular/router';
import { filter } from 'rxjs/operators';
import { MenuComponent } from './layouts/menu/menu.component';
import { ThemeService, ThemeType } from './../app/shared/features/home/services/theme.service';
import { HeaderComponent } from './layouts/header/header.component';
import { Component, OnInit, OnDestroy, NgZone } from '@angular/core';
import { Subject, takeUntil } from 'rxjs';
import { NgIf } from '@angular/common';
import { LoadingService } from './core/services/loading.service';
import { ModuleLoaderService } from './core/services/module-loader.service';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [
    RouterOutlet,
    ToastModule,
    SessionTimeoutModalComponent,
    LoadingComponent,
    OtpCodeComponent,
    CodigoMaestroModalComponent,
    MenuComponent,
    HeaderComponent,
    NgIf,
  ],
  template: `
    <app-header *ngIf="showHeader"></app-header>
    <router-outlet></router-outlet>
    <p-toast></p-toast>
    <app-session-timeout-modal></app-session-timeout-modal>
    <app-loading />
    <app-otp-code></app-otp-code>
    <app-codigo-maestro-modal></app-codigo-maestro-modal>
  `
})
export class AppComponent implements OnInit, OnDestroy {
  title = 'SIGPAZ';
  private lastModule: string = '';
  private initialLoadDone = false;
  showHeader: boolean = true;
  currentTheme: ThemeType = 'light';
  private destroy$ = new Subject<void>();
  private navigationTimeout: any;

  private readonly hideHeaderRoutes = [
    '/login',
    '/login?sessionExpired=true',
    '/login?sessionExpired=true&reason=inactivity',
    '/login?sessionExpired=true&reason=refresh_failed',
    '/login?sessionExpired=true&reason=idle_timeout',
    '/login?sessionExpired=true&reason=forced_logout',
    '/forgot-password',
    '/reset-password',
    '/security-questions',
    '/configue-questions',
    '/configure-security',
    '/home'


  ];

  constructor(
    private notificationService: NotificationService,
    private authService: AuthService,
    private router: Router,
    private themeService: ThemeService,
    private loadingService: LoadingService,
    private moduleLoader: ModuleLoaderService,
    private ngZone: NgZone
  ) {}

  ngOnInit(): void {
    this.themeService.theme$
      .pipe(takeUntil(this.destroy$))
      .subscribe(theme => {
        this.currentTheme = theme;
        document.body.classList.remove('light-theme', 'dark-theme', 'neon-theme');
        document.body.classList.add(`${theme}-theme`);
      });

    // Escuchar eventos de navegación
    this.router.events.pipe(
      filter(event => event instanceof NavigationStart ||
                      event instanceof RoutesRecognized ||
                      event instanceof NavigationEnd ||
                      event instanceof NavigationError)
    ).subscribe((event) => {
      this.ngZone.run(() => {
       if (event instanceof NavigationStart) {
  const url = event.url;
  const module = this.getModuleFromUrl(url);

  if (module && module !== this.lastModule) {
    console.log(`🚀 Iniciando navegación a: ${module}`);
    // Limpiar cualquier loading anterior
    this.moduleLoader.forceHideLoading();
    // Registrar el nuevo módulo
    this.moduleLoader.registerModuleLoading(module);
    this.lastModule = module;
  }
}

        if (event instanceof RoutesRecognized) {
          console.log(`📍 Ruta reconocida: ${event.url}`);
        }

        if (event instanceof NavigationEnd) {
  if (this.navigationTimeout) {
    clearTimeout(this.navigationTimeout);
  }

  const url = event.urlAfterRedirects;
  const baseUrl = url.split('?')[0];  // ✅ Extraer ruta base

  const shouldHide = this.hideHeaderRoutes.some(route =>
    url === route || url.startsWith(route + '/')
  );
  this.showHeader = !shouldHide;

  console.log(`📍 URL: ${url}, Base: ${baseUrl}, showHeader: ${this.showHeader}`);

  const module = this.getModuleFromUrl(baseUrl);

          if (module) {
            console.log(`✅ Navegación completada a: ${module}`);
          }

          // Notificar módulo cargado
          this.notificationService.addNotification({
            title: 'Navegación',
            message: `Accedió al módulo: ${module}`,
            type: 'info',
            module: 'sistema',
            metadata: { action: 'navigation', url: url }
          }).subscribe();
        }

        if (event instanceof NavigationError) {
          if (this.navigationTimeout) {
            clearTimeout(this.navigationTimeout);
          }
          this.moduleLoader.forceHideLoading();
          console.error('Error de navegación:', event.error);
        }
      });
    });
  }

  ngOnDestroy(): void {
    if (this.navigationTimeout) {
      clearTimeout(this.navigationTimeout);
    }
    this.destroy$.next();
    this.destroy$.complete();
  }

  private getModuleFromUrl(url: string): string {
    const moduleMap: { [key: string]: string } = {
      '/dashboard': 'Vista General Dashboard',
      '/personas': 'Gestión de Personas',
      '/catalogos': 'Catálogos del Sistema',
      '/denuncias': 'Gestión de Denuncias',
      //'/seguridad/auditorias': 'Gestión de Auditoría y Logs',
      '/seguridad/usuarios': 'Administración de Usuarios',
      '/seguridad/accesos': 'Administración de Accesos y Permisos',
      '/intermediaciones': 'Gestión de Intermediaciones',
      '/resoluciones': 'Gestión de Resoluciones',
      '/expedientes': 'Gestión de Expedientes',
      '/calendario': 'Gestión de Calendario y Asistencia',
      '/reportes': 'Gestión de Reportes y Estadísticas',
      '/personal': 'Gestión de Personal',
      '/manuales/usuario': 'Manuales de Usuario',
      '/backup': 'Gestión de Respaldo y Restauración',
    };

    for (const [route, moduleName] of Object.entries(moduleMap)) {
      if (url.includes(route)) {
        return moduleName;
      }
    }
    return '';
  }
}
