import { Injectable, Inject } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { BehaviorSubject, Observable, of, throwError } from 'rxjs';
import { catchError, finalize, filter, switchMap, take, tap } from 'rxjs/operators';
import { Router } from '@angular/router';
import { RefreshTokenResponse } from '../models/auth.models';
import { APP_CONFIG, AppConfig } from '../config/app-config.token';
import { ITokenStore } from '../interfaces/auth.interfaces';

@Injectable({ providedIn: 'root' })
export class TokenService implements ITokenStore {
  private readonly tokenKey = 'token';
  private refreshInProgress = false;
  private refreshSubject = new BehaviorSubject<string | null>(null);

  constructor(
    private http: HttpClient,
    private router: Router,
    @Inject(APP_CONFIG) private cfg: AppConfig
  ) {}

  getToken(): string | null {
    return localStorage.getItem(this.tokenKey);
  }

  setToken(token: string): void {
    if (token) {
      localStorage.setItem(this.tokenKey, token);
      console.log('✅ [TokenService] Token guardado, longitud:', token.length);
      const saved = localStorage.getItem(this.tokenKey);
      console.log('✅ [TokenService] Verificación:', saved ? 'Guardado correctamente' : 'ERROR: No se guardó');
    }
  }

  clearToken(): void {
    localStorage.removeItem(this.tokenKey);
    localStorage.removeItem('token_temp');
  }

  getTempToken(): string | null {
    return localStorage.getItem('token_temp');
  }

  buildBaseHeaders(): HttpHeaders {
    return new HttpHeaders({
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      'X-Requested-With': 'XMLHttpRequest'
    });
  }

  refreshToken(): Observable<RefreshTokenResponse> {
    const url = `${this.cfg.apiUrl}/auth/refrescar-token`;
    const currentToken = this.getToken();

    if (!currentToken) {
      return throwError(() => ({ success: false, message: 'No hay token para refrescar' }));
    }

    if (this.refreshInProgress) {
      return this.refreshSubject.pipe(
        filter(t => t !== null),
        take(1),
        switchMap(token => of({ success: true, access_token: token! }))
      );
    }

    this.refreshInProgress = true;
    this.refreshSubject.next(null);

    return this.http.post<RefreshTokenResponse>(url, {}, { headers: this.getAuthHeaders() }).pipe(
      tap((resp) => {
        if (resp.success && resp.access_token) {
          this.setToken(resp.access_token);
          this.refreshSubject.next(resp.access_token);
        } else {
          this.refreshSubject.next(null);
        }
      }),
      catchError((err) => {
        this.refreshSubject.next(null);
        // ✅ SOLO limpiar token, NO navegar (el interceptor maneja la navegación)
        if (err?.status === 401) {
          this.clearToken();
        }
        return throwError(() => err);
      }),
      finalize(() => {
        this.refreshInProgress = false;
      })
    );
  }

  updateAuthHeaders(newToken: string): void {
    this.setToken(newToken);
  }

  getAuthHeaders(useTempToken: boolean = false): HttpHeaders {
    const token = useTempToken ? this.getTempToken() : this.getToken();

    let headers = new HttpHeaders({
      'Content-Type': 'application/json',
      'Accept': 'application/json',
      'X-Requested-With': 'XMLHttpRequest'
    });

    if (token) {
      headers = headers.set('Authorization', `Bearer ${token}`);
    }

    return headers;
  }
}
