import { Injectable } from '@angular/core';
import { BlockedState } from '../models/login.models';

@Injectable({ providedIn: 'root' })
export class BlockedService {
  parseBlockedResponse(errorData: any): BlockedState {
    const blockedUntil = errorData?.bloqueado_hasta
      ? new Date(errorData.bloqueado_hasta)
      : new Date(Date.now() + 60 * 60 * 1000);

    return {
      isBlocked: true,
      message: errorData?.message || 'Usuario bloqueado temporalmente por múltiples intentos fallidos.',
      until: blockedUntil,
      minutes: 0,
      seconds: 0,
      remainingTime: ''
    };
  }
}
