import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ThemeService, ThemeType } from '../../services/theme.service';
import { Subject, takeUntil } from 'rxjs';

@Component({
  selector: 'app-theme-switcher',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="theme-switcher">
      <button
        *ngFor="let theme of themes"
        class="theme-btn"
        [class.active]="currentTheme === theme.value"
        [class]="theme.value"
        (click)="setTheme(theme.value)"
        [attr.title]="theme.label">
        <i [class]="theme.icon"></i>
        <span class="theme-label">{{ theme.label }}</span>
      </button>
    </div>
  `,
  styles: [`
    .theme-switcher {
      display: flex;
      gap: 33px;
      background: rgba(255, 255, 255, 0.05);
      padding: 6px;
      border-radius: 50px;
      backdrop-filter: blur(10px);
      border: 1px solid rgba(255, 255, 255, 0.1);
    }

    .theme-btn {
      display: flex;
      align-items: center;
      gap: 8px;
      padding: 8px 16px;
      border-radius: 40px;
      border: none;
      cursor: pointer;
      font-weight: 500;
      transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
      background: transparent;
      color: var(--text-secondary);

      i {
        font-size: 1rem;
      }

      .theme-label {
        font-size: 0.85rem;
      }

      &:hover {
        transform: translateY(-2px);
      }

      &.active {
        background: var(--primary);
        color: white;
        box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
      }

      &.light:hover:not(.active) {
        background: rgba(255, 255, 255, 0.2);
        color: #1f2937;
      }

      &.dark:hover:not(.active) {
        background: rgba(0, 0, 0, 0.3);
        color: white;
      }

      &.neon:hover:not(.active) {
        background: rgba(0, 240, 255, 0.2);
        color: #00f0ff;
        box-shadow: 0 0 10px rgba(0, 240, 255, 0.3);
      }
    }

    @media (max-width: 768px) {
      .theme-switcher {
        gap: 4px;
        padding: 4px;
      }

      .theme-btn {
        padding: 6px 12px;

        .theme-label {
          display: none;
        }

        i {
          font-size: 1.1rem;
        }
      }
    }
  `]
})
export class ThemeSwitcherComponent implements OnInit, OnDestroy {
  themes = [
    { value: 'light' as ThemeType, label: 'Claro', icon: 'pi pi-sun' },
    { value: 'dark' as ThemeType, label: 'Oscuro', icon: 'pi pi-moon' },
    { value: 'neon' as ThemeType, label: 'Neón', icon: 'pi pi-star' }
  ];

  currentTheme: ThemeType = 'light';
  private destroy$ = new Subject<void>();

  constructor(private themeService: ThemeService) {}

  ngOnInit(): void {
    this.themeService.theme$
      .pipe(takeUntil(this.destroy$))
      .subscribe(theme => {
        this.currentTheme = theme;
      });
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  setTheme(theme: ThemeType): void {
    this.themeService.setTheme(theme);
  }
}
