import { Injectable, OnDestroy, NgZone } from '@angular/core';
import { Subject, Observable } from 'rxjs';

declare const Pusher: any;

@Injectable({ providedIn: 'root' })
export class PusherService implements OnDestroy {
  private pusher: any = null;
  private channels: Map<string, any> = new Map();
  private connectionStatus = new Subject<boolean>();

  constructor(private ngZone: NgZone) {
    this.loadPusherScript();
  }

  private loadPusherScript(): void {
    if (typeof Pusher !== 'undefined') {
      this.initializePusher();
      return;
    }

    const script = document.createElement('script');
    script.src = 'https://js.pusher.com/8.4.0/pusher.min.js';
    script.onload = () => {
      console.log('✅ Pusher JS cargado');
      this.initializePusher();
    };
    script.onerror = () => {
      console.error('❌ Error cargando Pusher JS');
    };
    document.head.appendChild(script);
  }

  private initializePusher(): void {
    const token = localStorage.getItem('access_token');

    if (!token) {
      setTimeout(() => this.initializePusher(), 2000);
      return;
    }

    const config = {
      wsHost: 'localhost',
      wsPort: 8081,
      wssPort: 8081,
      forceTLS: false,
      enabledTransports: ['ws', 'wss'],
      disableStats: true,
      authEndpoint: 'http://localhost:8000/api/broadcasting/auth',
      auth: {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Accept': 'application/json'
        }
      }
    };

    try {
      this.pusher = new Pusher('knghnyhbqxpckqkm6zuz', config);

      this.pusher.connection.bind('connected', () => {
        this.ngZone.run(() => this.connectionStatus.next(true));
        console.log('✅ WebSocket conectado');
      });

      this.pusher.connection.bind('disconnected', () => {
        this.ngZone.run(() => this.connectionStatus.next(false));
        console.log('❌ WebSocket desconectado');
      });
    } catch (error) {
      console.error('❌ Error:', error);
    }
  }

  subscribePrivate(channelName: string, eventName: string): Observable<any> {
  return new Observable(observer => {
    if (!this.pusher) {
      observer.error('Pusher no inicializado');
      return; // ✅ Retorna undefined para cerrar el observable
    }

    try {
      const channel = this.pusher.subscribe(channelName);
      const handler = (data: any) => this.ngZone.run(() => observer.next(data));
      channel.bind(eventName, handler);

      const key = `${channelName}|${eventName}`;
      this.channels.set(key, { channel, handler, eventName, channelName });

      // ✅ Función de limpieza (return es opcional aquí)
      return () => {
        try {
          channel.unbind(eventName, handler);
          if (this.pusher) {
            this.pusher.unsubscribe(channelName);
          }
          this.channels.delete(key);
        } catch (e) {
          // Ignorar errores de limpieza
        }
      };
    } catch (error) {
      observer.error(error);
      return; // ✅ Retorna undefined
    }
  });
}
  getConnectionStatus(): Observable<boolean> {
    return this.connectionStatus.asObservable();
  }

  disconnect(): void {
    this.channels.forEach(({ channel, eventName, handler, channelName }) => {
      try {
        channel.unbind(eventName, handler);
        this.pusher?.unsubscribe(channelName);
      } catch (e) {}
    });
    this.channels.clear();

    if (this.pusher) {
      this.pusher.disconnect();
      this.pusher = null;
    }
  }

  ngOnDestroy(): void {
    this.disconnect();
  }
}
