import { Inject, Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { HttpClient } from '@angular/common/http';
import { TokenService } from './token.service';
import { UserProfile } from '../models/auth.models';
import { APP_CONFIG, AppConfig } from '../config/app-config.token';
import { IUserStore } from '../interfaces/auth.interfaces';

@Injectable({
  providedIn: 'root'
})
export class UserService implements IUserStore {
  private readonly userKey = 'currentUser';
  private currentUserSubject = new BehaviorSubject<UserProfile | null>(null);
  public currentUser$ = this.currentUserSubject.asObservable();

  constructor(
    private http: HttpClient,
    private tokenService: TokenService,
    @Inject(APP_CONFIG) private cfg: AppConfig
  ) {
    this.loadStoredUser();
  }

  saveUserData(userData: UserProfile): void {
    this.currentUserSubject.next(userData);
    localStorage.setItem(this.userKey, JSON.stringify(userData));
    sessionStorage.setItem('current_user', JSON.stringify(userData));
  }

  getCurrentUser(): UserProfile | null {
    const user = this.currentUserSubject.value;
    if (user) return user;
    const stored = localStorage.getItem(this.userKey);
    if (!stored) return null;
    try {
      return JSON.parse(stored) as UserProfile;
    } catch {
      return null;
    }
  }

  loadStoredUser(): void {
    const stored = localStorage.getItem(this.userKey);
    if (!stored) {
      const sessionUser = sessionStorage.getItem('current_user');
      if (sessionUser) {
        try {
          const user = JSON.parse(sessionUser) as UserProfile;
          this.currentUserSubject.next(user);
          localStorage.setItem(this.userKey, sessionUser);
        } catch {}
      }
      return;
    }
    try {
      const user = JSON.parse(stored) as UserProfile;
      this.currentUserSubject.next(user);
    } catch {}
  }

  clearUserData(): void {
    localStorage.removeItem(this.userKey);
    sessionStorage.removeItem('current_user');
    this.currentUserSubject.next(null);
  }

  getProfile(): Observable<any> {
    const url = `${this.cfg.apiUrl}/auth/me`;
    return this.http.get<any>(url, { headers: this.tokenService.getAuthHeaders() }).pipe(
      tap(resp => { if (resp?.success && resp.data) this.saveUserData(resp.data); })
    );
  }

  updateProfile(profile: any): Observable<any> {
    const url = `${this.cfg.apiUrl}/auth/update-profile`;
    return this.http.put<any>(url, profile, { headers: this.tokenService.getAuthHeaders() }).pipe(
      tap(resp => { if (resp?.success && resp.data) this.saveUserData(resp.data); })
    );
  }
}
