import { Component, OnInit, OnDestroy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ModalCommunicationService, ModalState } from '../../../core/services/modal-communication.service';
import { Subscription } from 'rxjs';
import { ModalService } from '../../../core/services/modal.service';

@Component({
  selector: 'app-codigo-maestro-modal',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <div *ngIf="isVisible" class="codigo-master-overlay" (click)="onOverlayClick($event)">
      <div class="codigo-master-modal" [style.zIndex]="modalState.zIndex">
        <div class="modal-header">
          <h3>🔐 Código Maestro Requerido</h3>
          <button class="close-btn" (click)="cancelar()">×</button>
        </div>
        <div class="modal-body">
          <p>{{ mensaje }}</p>
          <div class="codigo-input-group">
            <input
              type="password"
              class="codigo-input"
              [(ngModel)]="codigo"
              placeholder="Ingrese el código maestro"
              (keyup.enter)="confirmar()"
              [disabled]="isLoading"
              autofocus
            />
            <div *ngIf="isLoading" class="loading-spinner">
              <div class="spinner"></div>
              <span>Verificando código...</span>
            </div>
          </div>
          <div class="info-text">
            💡 Este código es requerido para realizar operaciones críticas en el sistema.
            Consulte con su administrador si no lo conoce.
          </div>
        </div>
        <div class="modal-footer">
          <button class="btn btn-secondary" (click)="cancelar()" [disabled]="isLoading">Cancelar</button>
          <button class="btn btn-primary" (click)="confirmar()" [disabled]="!codigo.trim() || isLoading">
            {{ isLoading ? 'Verificando...' : 'Confirmar' }}
          </button>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .codigo-master-overlay {
      position: fixed;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: rgba(0, 0, 0, 0.5);
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 9999;
    }

    .codigo-master-modal {
      background: white;
      border-radius: 12px;
      width: 90%;
      max-width: 400px;
      box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
      animation: slideIn 0.3s ease;
    }

    @keyframes slideIn {
      from {
        transform: translateY(-50px);
        opacity: 0;
      }
      to {
        transform: translateY(0);
        opacity: 1;
      }
    }

    .modal-header {
      padding: 16px 20px;
      border-bottom: 1px solid #e0e0e0;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }

    .modal-header h3 {
      margin: 0;
      color: #333;
      font-size: 18px;
    }

    .close-btn {
      background: none;
      border: none;
      font-size: 24px;
      cursor: pointer;
      color: #999;
    }

    .close-btn:hover {
      color: #333;
    }

    .modal-body {
      padding: 20px;
    }

    .modal-body p {
      margin: 0 0 16px 0;
      color: #666;
    }

    .codigo-input-group {
      margin: 16px 0;
    }

    .codigo-input {
      width: 100%;
      padding: 12px;
      border: 1px solid #ddd;
      border-radius: 8px;
      font-size: 16px;
      transition: all 0.3s;
    }

    .codigo-input:focus {
      outline: none;
      border-color: #667eea;
      box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
    }

    .codigo-input:disabled {
      background-color: #f5f5f5;
      cursor: not-allowed;
    }

    .loading-spinner {
      display: flex;
      align-items: center;
      gap: 10px;
      margin-top: 10px;
      padding: 8px;
      background: #f0f7ff;
      border-radius: 6px;
      color: #667eea;
      font-size: 14px;
    }

    .spinner {
      width: 16px;
      height: 16px;
      border: 2px solid #e0e0e0;
      border-top-color: #667eea;
      border-radius: 50%;
      animation: spin 0.8s linear infinite;
    }

    @keyframes spin {
      to { transform: rotate(360deg); }
    }

    .info-text {
      font-size: 12px;
      color: #999;
      margin-top: 12px;
      padding: 8px;
      background: #f5f5f5;
      border-radius: 6px;
    }

    .modal-footer {
      padding: 16px 20px;
      border-top: 1px solid #e0e0e0;
      display: flex;
      justify-content: flex-end;
      gap: 12px;
    }

    .btn {
      padding: 8px 16px;
      border-radius: 6px;
      font-size: 14px;
      cursor: pointer;
      transition: all 0.3s;
      border: none;
    }

    .btn-secondary {
      background: #f0f0f0;
      color: #666;
    }

    .btn-secondary:hover:not(:disabled) {
      background: #e0e0e0;
    }

    .btn-primary {
      background: linear-gradient(135deg, #667eea, #764ba2);
      color: white;
    }

    .btn-primary:hover:not(:disabled) {
      transform: translateY(-1px);
      box-shadow: 0 4px 12px rgba(102, 126, 234, 0.4);
    }

    .btn-primary:disabled, .btn-secondary:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }
  `]
})
export class CodigoMaestroModalComponent implements OnInit, OnDestroy {
  isVisible = false;
  modalState: ModalState = { isOpen: false, type: 'none', zIndex: 1000, position: {} };
  codigo = '';
  mensaje = 'Esta acción requiere el código maestro de seguridad.';
  isLoading = false;
  visible = false;
  private subscription?: Subscription;

  private modalSubscription: Subscription | null = null;

  constructor(
    private modalCommService: ModalCommunicationService,
    private cdr: ChangeDetectorRef,
    private modalService: ModalService,
  ) {}

  ngOnInit() {
    this.subscription = this.modalService.modalState$.subscribe(state => {
      if (this.visible !== state.codigoMaestroModal) {
        this.visible = state.codigoMaestroModal;
      }
    });
    this.modalSubscription = this.modalCommService.getModalState().subscribe((state: ModalState) => {
      console.log('📢 Modal state recibido:', state);
      if (state.type === 'codigoMaestro') {
        this.isVisible = state.isOpen;
        this.modalState = state;
        console.log('📢 isVisible actualizado a:', this.isVisible);
        this.cdr.detectChanges();

        if (state.isOpen) {
          this.codigo = '';
          this.isLoading = false;
          this.mensaje = 'Esta acción requiere el código maestro de seguridad.';
          setTimeout(() => {
            const input = document.querySelector('.codigo-input') as HTMLInputElement;
            if (input) input.focus();
          }, 100);
        }
      }
    });
  }

  ngOnDestroy() {
    this.subscription?.unsubscribe();
    if (this.modalSubscription) {
      this.modalSubscription.unsubscribe();
    }
  }

  onOverlayClick(event: MouseEvent) {
    if (event.target === event.currentTarget) {
      this.cancelar();
    }
  }

  confirmar() {
    console.log('🔐 Confirmar clickeado, código:', this.codigo ? '***' : 'vacío');
    if (this.codigo && this.codigo.trim()) {
      this.isLoading = true;
      this.mensaje = '🔐 Verificando código maestro...';
      this.cdr.detectChanges();

      this.modalCommService.submitCodigoMaestro(this.codigo.trim());

      // Mostrar éxito después de un breve momento
      setTimeout(() => {
        if (this.isVisible) {
          this.mensaje = '✅ Código verificado correctamente';
          this.cdr.detectChanges();
          setTimeout(() => {
            this.modalCommService.closeCodigoMaestroModal();
          }, 500);
        }
      }, 500);
    } else {
      this.mensaje = '❌ Por favor ingrese el código maestro';
      setTimeout(() => {
        this.mensaje = 'Esta acción requiere el código maestro de seguridad.';
        this.cdr.detectChanges();
      }, 2000);
    }
  }

  cancelar() {
    console.log('❌ Cancelar clickeado');
    this.modalCommService.submitCodigoMaestro('');
  }
}
