import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { Router } from '@angular/router';
import { MessageService } from 'primeng/api';
import { animate, style, transition, trigger } from '@angular/animations';
import { ChangeDetectorRef } from '@angular/core';

// PrimeNG Modules
import { ButtonModule } from 'primeng/button';
import { CardModule } from 'primeng/card';
import { InputTextModule } from 'primeng/inputtext';
import { DropdownModule } from 'primeng/dropdown';
import { MessagesModule } from 'primeng/messages';
import { ToastModule } from 'primeng/toast';
import { RippleModule } from 'primeng/ripple';
import { TooltipModule } from 'primeng/tooltip';

// Services
import { AuthService } from '../../../core/services/auth.service';
import { ThemeService } from './../home/services/theme.service';
import { query, stagger } from '@angular/animations';
// Models
import { SecurityQuestion, SecurityAnswer, ThemeType } from './models/security.models';
import { ThemeSwitcherComponent } from './../../../shared/features/home/components/theme-switcher/theme-switcher.component';

@Component({
  selector: 'app-configure-security',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    ButtonModule,
    CardModule,
    InputTextModule,
    DropdownModule,
    MessagesModule,
    ToastModule,
    RippleModule,
    ThemeSwitcherComponent,
    TooltipModule
  ],
  templateUrl: './configure-security.component.html',
  styleUrls: ['./configure-security.component.less'],
  animations: [
    trigger('fadeIn', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(-20px)' }),
        animate('500ms cubic-bezier(0.4, 0, 0.2, 1)',
          style({ opacity: 1, transform: 'translateY(0)' }))
      ])
    ]),
    trigger('staggerAnimation', [
      transition('* => *', [
        query(':enter', [
          style({ opacity: 0, transform: 'translateX(-20px)' }),
          stagger(100, [
            animate('400ms ease-out', style({ opacity: 1, transform: 'translateX(0)' }))
          ])
        ], { optional: true })
      ])
    ])
  ]
})
export class ConfigureSecurityComponent implements OnInit {
  private readonly API_URL = 'http://localhost:8000/api/v1';


  themeOptions: { label: string; value: ThemeType; icon: string }[] = [
  { label: '☀️ Claro', value: 'light', icon: 'pi pi-sun' },
  { label: '🌙 Oscuro', value: 'dark', icon: 'pi pi-moon' },
  { label: '⚡ Neón', value: 'neon', icon: 'pi pi-bolt' }
];

  // Tema
  currentTheme: ThemeType = 'light';

  preguntasDisponibles: SecurityQuestion[] = [];
  respuestas: SecurityAnswer[] = [
    { pregunta_id: 0, respuesta: '' },
    { pregunta_id: 0, respuesta: '' },
    { pregunta_id: 0, respuesta: '' }
  ];

  loading = true;
  formularioEnviado = false;
  usuarioId: number | null = null;
private preguntasCargadas = false;

  constructor(
    private authService: AuthService,
    private http: HttpClient,
    private router: Router,
    private messageService: MessageService,
     private cdr: ChangeDetectorRef,
    private themeService: ThemeService
  ) {
    this.themeService.theme$.subscribe(theme => {
      this.currentTheme = theme;
       this.cdr.detectChanges();
    });
  }

  ngOnInit(): void {
    this.usuarioId = this.authService.getSetupUsuarioId();
    if (!this.usuarioId) {
      this.router.navigate(['/login']);
      return;
    }
    if (!this.preguntasCargadas) {
      this.loadPreguntasDisponibles();
    }
  }

  private loadPreguntasDisponibles(): void {
    // ✅ Evitar recargas múltiples
    if (this.preguntasCargadas) {
      console.log('⚠️ Preguntas ya cargadas, omitiendo recarga');
      return;
    }

    this.loading = true;
     this.cdr.detectChanges();
    const tempToken = localStorage.getItem('token_temp');

    if (!tempToken) {
      this.loading = false;
      this.showMessage('error', 'Error', 'Sesión no válida');
      this.router.navigate(['/login']);
      return;
    }

    const headers = new HttpHeaders({
      'Authorization': `Bearer ${tempToken}`,
      'Content-Type': 'application/json',
      'Accept': 'application/json'
    });

    this.http.get<{success: boolean, data: SecurityQuestion[]}>(`${this.API_URL}/auth/preguntas-disponibles`, { headers })
      .subscribe({
        next: (response) => {
          console.log('📥 Preguntas recibidas:', response);

          if (response.success && response.data && response.data.length > 0) {
            this.preguntasDisponibles = response.data;
            this.preguntasCargadas = true;  // ✅ Marcar como cargadas
            console.log('✅ Preguntas cargadas:', this.preguntasDisponibles.length);
          } else {
            console.warn('⚠️ No hay preguntas disponibles');
            this.preguntasDisponibles = this.getDefaultQuestions();
          }

          this.loading = false;
          this.cdr.detectChanges();
        },
        error: (error) => {
          console.error('❌ Error cargando preguntas:', error);
          this.preguntasDisponibles = this.getDefaultQuestions();
          this.showMessage('error', 'Error', 'No se pudieron cargar las preguntas');
          this.loading = false;
          this.cdr.detectChanges();
        }
      });
  }

  private getDefaultQuestions(): SecurityQuestion[] {
    return [
      { pregunta_id: 1, texto: '¿Cuál es el nombre de tu primera mascota?' },
      { pregunta_id: 2, texto: '¿En qué ciudad naciste?' },
      { pregunta_id: 3, texto: '¿Cuál es tu comida favorita?' },
      { pregunta_id: 4, texto: '¿Nombre de tu mejor amigo de la infancia?' },
      { pregunta_id: 5, texto: '¿Color favorito?' },
      { pregunta_id: 6, texto: '¿Modelo de tu primer auto?' }
    ];
  }

  isFormValid(): boolean {
    const preguntasIds = this.respuestas.map(r => r.pregunta_id);
    const uniqueIds = new Set(preguntasIds.filter(id => id > 0));
    const hasThreeUniqueQuestions = uniqueIds.size === 3;
    const allAnswersFilled = this.respuestas.every(r => r.respuesta.trim().length > 0 && r.pregunta_id > 0);
    return hasThreeUniqueQuestions && allAnswersFilled;
  }

  onSubmit(): void {
    if (!this.isFormValid()) {
      this.showMessage('error', 'Error', 'Debe seleccionar 3 preguntas diferentes y proporcionar respuestas');
      this.formularioEnviado = true;
      return;
    }

    this.loading = true;

    const formData = {
      respuestas: this.respuestas
        .filter(r => r.pregunta_id > 0 && r.respuesta.trim())
        .map(r => ({ pregunta_id: r.pregunta_id, respuesta: r.respuesta.trim() }))
    };

    const headers = new HttpHeaders({
      'Authorization': `Bearer ${localStorage.getItem('token_temp')}`,
      'Content-Type': 'application/json'
    });

    this.http.post(`${this.API_URL}/auth/configurar-preguntas`, formData, { headers })
      .subscribe({
        next: (response: any) => {
          if (response.success) {
            if (response.access_token) {
              localStorage.setItem('token', response.access_token);
              localStorage.removeItem('token_temp');
            }
            sessionStorage.setItem('just_configured_security', 'true');
            this.showMessage('success', '¡Configuración exitosa!', 'Preguntas configuradas correctamente');

            setTimeout(() => {
              this.router.navigate(['/dashboard']);
            }, 2000);
          } else {
            this.showMessage('error', 'Error', response.message || 'Error en la configuración');
            this.loading = false;
          }
        },
        error: (error) => {
          this.showMessage('error', 'Error', error.error?.message || 'No se pudieron guardar las preguntas');
          this.loading = false;
        }
      });
  }

  logout(): void {
    this.authService.clearAuthData();
    this.router.navigate(['/login']);
  }

  changeTheme(theme: ThemeType): void {
    this.currentTheme = theme;
    this.themeService.setTheme(theme);
  }

  private showMessage(severity: string, summary: string, detail: string): void {
    this.messageService.add({ severity, summary, detail, life: 5000 });
  }
}
