import { Component, OnInit, OnDestroy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { interval, Subscription } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { AuthService } from '../../../core/services/auth.service';
import { ModalCommunicationService, ModalState } from '../../../core/services/modal-communication.service';
import { Clipboard } from '@angular/cdk/clipboard';
import { TimeFormatPipe } from './../../pipes/time-format.pipe';
import { ModalService } from '../../../core/services/modal.service';

@Component({
  selector: 'app-otp-code',
  standalone: true,
  imports: [CommonModule,TimeFormatPipe],
  template: `
    <div *ngIf="isVisible"
         class="otp-modal"
         [style.zIndex]="modalState.zIndex"
         [style.bottom]="modalState.position.bottom"
         [style.right]="modalState.position.right"
         [class.minimized]="isMinimized">

      <div class="otp-header" (click)="toggleMinimize()">
        <div class="header-content">
          <span class="icon">🔐</span>
          <span class="title">Código Maestro</span>
          <span class="status-badge" [class.expiring]="tiempoRestanteVigencia < 60">
            {{ tiempoRestanteVigencia | timeFormat }}
          </span>
        </div>
        <button class="close-btn" (click)="closeModal()">×</button>
      </div>

      <div *ngIf="!isMinimized" class="otp-content">
        <div class="codigo-container">
          <div class="codigo-label">Código de acceso maestro</div>
          <div class="codigo-wrapper">
            <div class="codigo-valor">{{ codigoData?.codigo || 'CARGANDO...' }}</div>
            <button class="copy-btn"
                    (click)="copiarCodigo()"
                    [disabled]="!codigoData?.codigo || copiando || codigoExpirado">
              <span class="copy-icon">{{ copiado ? '✓' : '📋' }}</span>
            </button>
          </div>
          <div class="codigo-helper">Codigo de acceso Maestro</div>
        </div>

        <div class="info-grid">
          <div class="info-item">
            <span class="info-icon">⏱️</span>
            <div class="info-content">
              <div class="info-label">Vigencia</div>
              <div class="info-value" [class.expiring-text]="tiempoRestanteVigencia < 60">
                {{ tiempoRestanteVigencia | timeFormat }}
              </div>
            </div>
          </div>

          <div class="info-item">
            <span class="info-icon">📝</span>
            <div class="info-content">
              <div class="info-label">Usos restantes</div>
              <div class="info-value" [class.low-uses]="(codigoData?.usos_restantes || 0) <= 2">
                {{ codigoData?.usos_restantes || 0 }}
              </div>
            </div>
          </div>
        </div>

        <button class="regenerate-btn"
                (click)="regenerarCodigo()"
                [disabled]="!puedeRegenerar || regenerando">
          <span class="btn-icon">🔄</span>
          {{ regenerando ? 'Generando...' : 'Regenerar código' }}
        </button>

        <div class="info-message" *ngIf="codigoExpirado">
          ⚠️ El código ha expirado. Por favor, regenere uno nuevo.
        </div>
        <div class="info-message" *ngIf="!codigoExpirado">
          💡 Este código es solicitado por el sistema requiere la verificación del codigo de acceso del administrador, por favor comunícate con él.
        </div>
      </div>
    </div>
  `,
  styles: [`
    .otp-modal {
  position: fixed;
  background: linear-gradient(135deg, #667eea, #764ba2);
  border-radius: 16px;
  color: white;
  box-shadow: 0 10px 40px rgba(0,0,0,0.3);
  font-family: monospace;
  transition: all 0.3s ease;
  width: 280px;
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.2);

  &.minimized {
    width: auto;

    .otp-content {
      display: none;
    }
  }
}

    .otp-header {
      padding: 12px 16px;
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
      border-bottom: 1px solid rgba(255,255,255,0.2);
      user-select: none;

      &:hover {
        background: rgba(255,255,255,0.1);
      }

      .header-content {
        display: flex;
        align-items: center;
        gap: 12px;
        flex: 1;

        .icon {
          font-size: 18px;
        }

        .title {
          font-weight: bold;
          font-size: 14px;
        }

        .status-badge {
          font-size: 11px;
          background: rgba(0,0,0,0.3);
          padding: 2px 6px;
          border-radius: 12px;

          &.expiring {
            background: #ff6b6b;
            animation: pulse 1s infinite;
          }
        }
      }

      .close-btn {
        background: rgba(255,255,255,0.2);
        border: none;
        color: white;
        width: 24px;
        height: 24px;
        border-radius: 12px;
        cursor: pointer;
        font-size: 18px;
        display: flex;
        align-items: center;
        justify-content: center;

        &:hover {
          background: rgba(255,255,255,0.3);
        }
      }
    }

    .otp-content {
      padding: 16px;

      .codigo-container {
        text-align: center;
        margin-bottom: 20px;

        .codigo-label {
          font-size: 11px;
          text-transform: uppercase;
          letter-spacing: 1px;
          opacity: 0.8;
          margin-bottom: 8px;
        }

        .codigo-wrapper {
          display: flex;
          align-items: center;
          gap: 8px;
          justify-content: center;
          margin-bottom: 8px;

          .codigo-valor {
            font-size: 32px;
            font-weight: bold;
            letter-spacing: 4px;
            background: rgba(0,0,0,0.3);
            padding: 12px;
            border-radius: 8px;
          }

          .copy-btn {
            background: rgba(255,255,255,0.2);
            border: 1px solid rgba(255,255,255,0.3);
            color: white;
            width: 44px;
            height: 44px;
            border-radius: 8px;
            cursor: pointer;
            font-size: 18px;
            transition: all 0.3s;
            display: flex;
            align-items: center;
            justify-content: center;

            &:hover:not(:disabled) {
              background: rgba(255,255,255,0.3);
              transform: scale(1.05);
            }

            &.copied {
              background: #4caf50;
              border-color: #4caf50;
            }

            &:disabled {
              opacity: 0.5;
              cursor: not-allowed;
            }
          }
        }

        .codigo-helper {
          font-size: 11px;
          opacity: 0.7;
        }
      }

      .info-grid {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 12px;
        margin-bottom: 20px;

        .info-item {
          display: flex;
          align-items: center;
          gap: 8px;
          background: rgba(0,0,0,0.2);
          padding: 8px;
          border-radius: 8px;

          .info-icon {
            font-size: 20px;
          }

          .info-content {
            flex: 1;

            .info-label {
              font-size: 10px;
              opacity: 0.7;
            }

            .info-value {
              font-size: 14px;
              font-weight: bold;

              &.expiring-text {
                color: #ff6b6b;
                animation: pulse 1s infinite;
              }

              &.low-uses {
                color: #ffa502;
              }
            }
          }
        }
      }

      .regenerate-btn {
        width: 100%;
        padding: 10px;
        background: rgba(255,255,255,0.2);
        border: 1px solid rgba(255,255,255,0.3);
        color: white;
        border-radius: 8px;
        cursor: pointer;
        font-weight: 600;
        transition: all 0.3s;
        margin-bottom: 12px;

        &:hover:not(:disabled) {
          background: rgba(255,255,255,0.3);
          transform: translateY(-2px);
        }

        &:disabled {
          opacity: 0.5;
          cursor: not-allowed;
        }
      }

      .info-message {
        font-size: 11px;
        opacity: 0.7;
        text-align: center;
        line-height: 1.4;
      }
    }

    @keyframes pulse {
      0%, 100% {
        opacity: 1;
      }
      50% {
        opacity: 0.6;
      }
    }
  `]
})
export class OtpCodeComponent implements OnInit, OnDestroy {
  codigoData: any = null;
  tiempoRestanteVigencia = 0;
  regenerando = false;
  copiando = false;
  copiado = false;
  isVisible = false;
  isMinimized = false;
  puedeRegenerar = false;
  codigoExpirado = false;
  visible = false;
  private subscription?: Subscription;

  modalState: ModalState = {
    isOpen: false,
    type: 'none',
    zIndex: 1000,
    position: { bottom: '20px', right: '20px' }
  };

  private intervalSubscription: Subscription | null = null;
  private modalSubscription: Subscription | null = null;
  private eventsSubscription: Subscription | null = null;

  constructor(
    private http: HttpClient,
    private authService: AuthService,
    private modalCommService: ModalCommunicationService,
    private clipboard: Clipboard,
    private modalService: ModalService,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit() {
     this.subscription = this.modalService.modalState$.subscribe(state => {
      if (this.visible !== state.otpModal) {
        this.visible = state.otpModal;
      }
    });
    this.modalSubscription = this.modalCommService.getModalState().subscribe((state: ModalState) => {
      switch (state.type) {
        case 'otp':
          this.isVisible = state.isOpen;
          this.modalState = { ...state };
          if (state.isOpen) {
            this.cargarCodigo();
            this.iniciarContador();
          } else {
            this.detenerContador();
          }
          break;

        case 'chat':
          if (this.isVisible) {
            this.isVisible = false;
          }
          break;

        case 'none':
          if (this.isVisible) {
            this.isVisible = false;
          }
          break;
      }
      this.cdr.detectChanges();
    });

    this.eventsSubscription = this.modalCommService.getEvents().subscribe(event => {
      if (event === 'toggleChat' && this.isVisible) {
        this.isMinimized = !this.isMinimized;
        this.cdr.detectChanges();
      }
    });
  }

  ngOnDestroy() {
    this.subscription?.unsubscribe();
    this.detenerContador();
    if (this.modalSubscription) {
      this.modalSubscription.unsubscribe();
    }
    if (this.eventsSubscription) {
      this.eventsSubscription.unsubscribe();
    }
  }

  private detenerContador() {
    if (this.intervalSubscription) {
      this.intervalSubscription.unsubscribe();
      this.intervalSubscription = null;
    }
  }

  toggleMinimize() {
    this.isMinimized = !this.isMinimized;
    this.cdr.detectChanges();
  }

  closeModal() {
    this.modalCommService.closeOTPModal();
  }

cargarCodigo() {
  this.http.get(`${environment.apiUrl}/codigo-otp`).subscribe({
    next: (res: any) => {
      this.codigoData = res.data;
      this.codigoExpirado = false;
      this.puedeRegenerar = res.data.puede_regenerar === true;
      this.verificarExpiracion();
      this.cdr.detectChanges();
    },
    error: (err) => {
      console.error('Error cargando código:', err);
      this.codigoData = {
        id: 1,
        codigo: 'DEMO-001',
        usos_restantes: 0,  // ✅ Simular sin usos
        puede_regenerar: true,
        puede_regenerar_en: null,
        expira_en: new Date(Date.now() + 5 * 60000).toISOString(),
        activo: false
      };
      this.codigoExpirado = true;
      this.puedeRegenerar = true;  // ✅ Habilitar botón
      this.cdr.detectChanges();
    }
  });
}

copiarCodigo() {
  if (!this.codigoData?.codigo) return;
  if (this.codigoData.usos_restantes <= 0) {
    this.codigoExpirado = true;
    this.puedeRegenerar = true;  // ✅ Habilitar botón
    this.cdr.detectChanges();
    return;
  }

  this.copiando = true;
  this.cdr.detectChanges();

  // Copiar al portapapeles
  this.clipboard.copy(this.codigoData.codigo);

  this.copiado = true;
  setTimeout(() => {
    this.copiado = false;
    this.cdr.detectChanges();
  }, 2000);

  // Consumir el código
  this.http.post(`${environment.apiUrl}/codigo-otp/usar`, {
    codigo: this.codigoData.codigo
  }).subscribe({
    next: (res: any) => {
      console.log('✅ Código consumido correctamente');
      if (res.data) {
        this.codigoData.usos_restantes = res.data.usos_restantes;

        // ✅ Si ya no quedan usos, habilitar regeneración
        if (this.codigoData.usos_restantes <= 0) {
          this.codigoExpirado = true;
          this.puedeRegenerar = true;  // ✅ Habilitar botón
          console.log('🔓 Sin usos, botón regenerar habilitado');
        }
      }
      this.copiando = false;
      this.cdr.detectChanges();
    },
    error: (err) => {
      console.error('Error al consumir código:', err);
      this.copiando = false;
      this.cdr.detectChanges();
    }
  });
}
  regenerarCodigo() {
    if (!this.puedeRegenerar) return;

    this.regenerando = true;
    this.cdr.detectChanges();

    this.http.post(`${environment.apiUrl}/codigo-otp/regenerar`, {
      codigo_id: this.codigoData?.id
    }).subscribe({
      next: (res: any) => {
        this.codigoData = res.data;
        this.regenerando = false;
        this.copiado = false;
        this.codigoExpirado = false;
        this.actualizarPuedeRegenerar();
        this.cdr.detectChanges();

        // Reiniciar el contador
        this.detenerContador();
        this.iniciarContador();
      },
      error: (err) => {
        console.error('Error regenerando código:', err);
        this.regenerando = false;
        this.cdr.detectChanges();
      }
    });
  }

private actualizarPuedeRegenerar() {
  if (!this.codigoData) {
    this.puedeRegenerar = false;
    return;
  }

  // ✅ Si el código está expirado o no tiene usos, puede regenerar
  const expirado = new Date(this.codigoData.expira_en) <= new Date();
  const sinUsos = this.codigoData.usos_restantes <= 0;

  if (expirado || sinUsos) {
    this.puedeRegenerar = true;
  } else {
    // Si está activo, usar el valor del backend para el cooldown
    this.puedeRegenerar = this.codigoData.puede_regenerar === true;
  }

  console.log('🔄 puedeRegenerar:', this.puedeRegenerar, '| expirado:', expirado, '| sinUsos:', sinUsos);
}

private verificarExpiracion() {
  if (this.codigoData?.expira_en) {
    const ahora = new Date();
    const expira = new Date(this.codigoData.expira_en);
    const expirado = ahora >= expira;
    const sinUsos = this.codigoData.usos_restantes <= 0;

    this.codigoExpirado = expirado || sinUsos;

    // ✅ Si expiró o no tiene usos, habilitar botón regenerar
    if (this.codigoExpirado) {
      this.puedeRegenerar = true;
      console.log('🔓 Código expirado/sin usos, botón regenerar habilitado');
    }
  }
}

private iniciarContador() {
  this.detenerContador();

  this.intervalSubscription = interval(1000).subscribe(() => {
    if (this.codigoData?.expira_en) {
      const ahora = new Date();
      const expira = new Date(this.codigoData.expira_en);
      const diffSegundos = Math.floor((expira.getTime() - ahora.getTime()) / 1000);

      this.tiempoRestanteVigencia = Math.max(0, diffSegundos);

      // ✅ Cuando el tiempo expira, solo marcar como expirado y habilitar regeneración
      if (this.tiempoRestanteVigencia <= 0 && !this.codigoExpirado) {
        console.log('⏰ Código expirado, habilitando botón regenerar');
        this.codigoExpirado = true;

        // ✅ NO llamar a cargarCodigo() automáticamente
        // ✅ Solo habilitar el botón de regenerar
        this.puedeRegenerar = true;

        this.cdr.detectChanges();
      }

      this.cdr.detectChanges();
    }
  });
}

}

