  getRoles(): Observable<Rol[]> {
  return this.http.get<any>(`${this.apiUrl}/catalogos/roles`).pipe(
    map(response => {
      console.log('🔍 Roles - Respuesta cruda:', response);

      let data: any[] = [];
      if (response?.success && response.data) {
        data = Array.isArray(response.data) ? response.data : [response.data];
      } else if (Array.isArray(response)) {
        data = response;
      }

      return data.map((item: any) => ({
        rol_id: item.rol_id || item.id,
        nombre: item.nombre,
        nombre_rol: item.nombre,
        descripcion: item.descripcion || '',
        activo: item.activo ?? true
      }));
    }),
    tap((data: Rol[]) => console.log('✅ Roles mapeados:', data)),
    catchError(this.handleError('getRoles', 'roles'))
  );
}
