  getTiposConflicto(): Observable<TipoConflicto[]> {
  return this.http.get<any>(`${this.apiUrl}/catalogos/tipos-conflicto`).pipe(
    map((response: any) => {
      console.log('🔍 Tipos conflicto - Respuesta cruda:', response);

      // Extraer data con tipo explícito
      let data: any[] = [];
      if (response?.success && response.data) {
        data = Array.isArray(response.data) ? response.data : [response.data];
      } else if (Array.isArray(response)) {
        data = response;
      }

      // 👈 TIPO EXPLÍCITO EN EL PARÁMETRO
      return data.map((item: BackendTipoConflicto) => ({
        id: item.tipo_conflicto_id,
        tipo_conflicto_id: item.tipo_conflicto_id,
        nombre: item.nombre || '',
        descripcion: item.descripcion,
        activo: item.activo ?? true,
        estado: item.activo ?? true
      }));
    }),
    tap((data: TipoConflicto[]) => console.log('✅ Tipos conflicto mapeados:', data)),
    catchError(this.handleError('getTiposConflicto', 'tipos-conflicto'))
  );
}

