import { Injectable } from '@angular/core';
import { HttpClient, HttpParams, HttpHeaders } from '@angular/common/http';
import { Observable, throwError, of } from 'rxjs';
import { catchError, map, tap } from 'rxjs/operators';
import { environment } from '../../environments/environment';
import { AuthService } from '../core/services/auth.service';
import { NotificationService } from '../core/services/notification/notification.service';

// ========== INTERFACES ACTUALIZADAS ==========
export interface Personal {
  personal_id: number;
  persona_id: number;
  cargo_id: number;
  fecha_ingreso: string;
  fecha_egreso?: string;
  observaciones?: string;
  usuario_creacion_id: number;      // ✅ EXISTE EN BACKEND
  usuario_actualizacion_id?: number; // ✅ EXISTE EN BACKEND
  activo: boolean;
  fuente_registro: string;
  fecha_creacion: string;
  fecha_actualizacion?: string;

  // Relaciones
  persona?: {
    persona_id: number;
    nombre_completo: string;
    nombres: string;
    apellidos: string;
    numero_documento: string;
    tipo_documento?: string;
    foto_cifrada?: string;
    correo?: string;
    telefono?: string;
  };
  cargo?: {
    cargo_id: number;
    nombre: string;
    nombre_cargo?: string;
    descripcion?: string;
  };
  usuario_creacion?: {              // ✅ Relación con usuario que creó
    usuario_id: number;
    nombre_usuario: string;
  };
  usuario_actualizacion?: {         // ✅ Relación con usuario que actualizó
    usuario_id: number;
    nombre_usuario: string;
  };
}

export interface CreatePersonalDTO {
  persona_id: number;
  cargo_id: number;
  fecha_ingreso: string;
  fecha_egreso?: string;
  observaciones?: string;
  usuario_actualizacion_id?: number; // ✅ AGREGADO - viene del auth
  usuario_creacion_id: number;      // ✅ AGREGADO - viene del auth
  activo?: boolean;
  fuente_registro?: string;
}

export interface UpdatePersonalDTO {
  cargo_id?: number;
  fecha_ingreso?: string;
  fecha_egreso?: string;
  observaciones?: string;
  usuario_actualizacion_id?: number; // ✅ AGREGADO - viene del auth
  activo?: boolean;
}

export interface PersonalResponse {
  success: boolean;
  message?: string;
  data?: Personal;
  errors?: Record<string, string[]>;
}


export interface PersonalListResponse {
  success: boolean;
  message?: string;
  data: Personal[];
  meta?: {
    total: number;
    per_page: number;
    current_page: number;
    last_page: number;
    from: number;
    to: number;
  };
}

// ========== PATRÓN STRATEGY PARA PERMISOS ==========
export interface PersonalPermisoStrategy {
  puedeVer(): boolean;
  puedeCrear(): boolean;
  puedeActualizar(): boolean;
  puedeEliminar(): boolean;
  getPermisosEspecificos(): string[];
}

class AdministradorPersonalStrategy implements PersonalPermisoStrategy {
  puedeVer(): boolean { return true; }
  puedeCrear(): boolean { return true; }
  puedeActualizar(): boolean { return true; }
  puedeEliminar(): boolean { return true; }
  getPermisosEspecificos(): string[] {
    return ['ver', 'crear', 'editar', 'eliminar', 'reportes', 'exportar'];
  }
}

class TecnicoPersonalStrategy implements PersonalPermisoStrategy {
  puedeVer(): boolean { return true; }
  puedeCrear(): boolean { return true; }
  puedeActualizar(): boolean { return true; }
  puedeEliminar(): boolean { return false; }
  getPermisosEspecificos(): string[] {
    return ['ver', 'crear', 'editar', 'reportes'];
  }
}

class UsuarioAvanzadoPersonalStrategy implements PersonalPermisoStrategy {
  puedeVer(): boolean { return true; }
  puedeCrear(): boolean { return false; }
  puedeActualizar(): boolean { return false; }
  puedeEliminar(): boolean { return false; }
  getPermisosEspecificos(): string[] {
    return ['ver', 'reportes'];
  }
}

class UsuarioEstandarPersonalStrategy implements PersonalPermisoStrategy {
  puedeVer(): boolean { return true; }
  puedeCrear(): boolean { return false; }
  puedeActualizar(): boolean { return false; }
  puedeEliminar(): boolean { return false; }
  getPermisosEspecificos(): string[] {
    return ['ver'];
  }
}

export class PersonalPermisoFactory {
  static create(rolId: number, permisos: number[]): PersonalPermisoStrategy {
    if (rolId === 1 || permisos.includes(1)) {
      return new AdministradorPersonalStrategy();
    }
    if (rolId === 2 || permisos.includes(2)) {
      return new TecnicoPersonalStrategy();
    }
    if (rolId === 3 || permisos.includes(3)) {
      return new UsuarioAvanzadoPersonalStrategy();
    }
    return new UsuarioEstandarPersonalStrategy();
  }
}

@Injectable({
  providedIn: 'root'
})
export class PersonalService {
  private apiUrl = `${environment.apiUrl}/personal`;
  private permisosStrategy: PersonalPermisoStrategy | null = null;

  constructor(
    private http: HttpClient,
    private authService: AuthService,
    private notificationService: NotificationService
  ) {
    this.inicializarPermisos();
  }

  // ========== PERMISOS ==========
  private inicializarPermisos(): void {
    const user = this.authService.getCurrentUser();
    if (user) {
      const permisosStr = localStorage.getItem('user_permisos');
      const permisos = permisosStr ? JSON.parse(permisosStr) : [];
      this.permisosStrategy = PersonalPermisoFactory.create(user.rol_id, permisos);
    }
  }

  puedeVer(): boolean { return this.permisosStrategy?.puedeVer() ?? false; }
  puedeCrear(): boolean { return this.permisosStrategy?.puedeCrear() ?? false; }
  puedeActualizar(): boolean { return this.permisosStrategy?.puedeActualizar() ?? false; }
  puedeEliminar(): boolean { return this.permisosStrategy?.puedeEliminar() ?? false; }

  // ========== MÉTODOS CRUD ==========

  /**
   * Listar personal con filtros
   * GET /api/v1/personal
   */
  listarPersonal(filtros?: any): Observable<PersonalListResponse> {
    let params = new HttpParams();

    if (filtros) {
      Object.keys(filtros).forEach(key => {
        if (filtros[key] !== null && filtros[key] !== undefined && filtros[key] !== '') {
          const value = typeof filtros[key] === 'boolean'
                    ? filtros[key].toString()
                    : filtros[key].toString();
                params = params.append(key, value);
        }
      });
    }

    return this.http.get<PersonalListResponse>(this.apiUrl, { params }).pipe(
      tap(response => console.log('📥 Personal listado:', response)),
      catchError(this.handleError)
    );
  }

  /**
   * Obtener personal por ID
   * GET /api/v1/personal/{id}
   */
  obtenerPersonal(id: number): Observable<PersonalResponse> {
    return this.http.get<PersonalResponse>(`${this.apiUrl}/${id}`).pipe(
      tap(response => console.log('📥 Personal obtenido:', response)),
      catchError(this.handleError)
    );
  }



/**
 * Actualizar personal
 * PUT /api/v1/personal/{id}
 */
actualizarPersonal(id: number, datos: UpdatePersonalDTO): Observable<PersonalResponse> {
  if (!this.puedeActualizar()) {
    this.notificationService.showError('No tiene permisos para actualizar personal');
    return throwError(() => new Error('No tiene permisos para actualizar personal'));
  }

  // ✅ AGREGAR usuario_actualizacion_id del usuario actual
  const user = this.authService.getCurrentUser();
  if (user) {
    datos.usuario_actualizacion_id = user.usuario_id;
  }

  console.log('📤 Actualizando personal:', { id, datos });

  return this.http.put<PersonalResponse>(`${this.apiUrl}/${id}`, datos).pipe(
    tap(response => {
      console.log('📥 Respuesta actualización:', response);
      if (response.success) {
        this.notificationService.showSuccess(response.message || 'Personal actualizado exitosamente');
      }
    }),
    catchError(this.handleError)
  );
}

  /**
   * Eliminar personal (soft delete)
   * DELETE /api/v1/personal/{id}
   */
  eliminarPersonal(id: number): Observable<PersonalResponse> {
    if (!this.puedeEliminar()) {
      this.notificationService.showError('No tiene permisos para eliminar personal');
      return throwError(() => new Error('No tiene permisos para eliminar personal'));
    }

    return this.http.delete<PersonalResponse>(`${this.apiUrl}/${id}`).pipe(
      tap(response => {
        if (response.success) {
          this.notificationService.showSuccess(response.message || 'Personal eliminado exitosamente');
        }
      }),
      catchError(this.handleError)
    );
  }

  // ========== MÉTODOS ESPECIALIZADOS ==========

  /**
   * Activar personal
   * POST /api/v1/personal/{id}/activar
   */
  activarPersonal(id: number): Observable<PersonalResponse> {
    if (!this.puedeActualizar()) {
      return throwError(() => new Error('No tiene permisos para activar personal'));
    }

    return this.http.post<PersonalResponse>(`${this.apiUrl}/${id}/activar`, {}).pipe(
      tap(response => {
        if (response.success) {
          this.notificationService.showSuccess('Personal activado exitosamente');
        }
      }),
      catchError(this.handleError)
    );
  }

  /**
   * Desactivar personal
   * POST /api/v1/personal/{id}/desactivar
   */
desactivarPersonal(id: number): Observable<PersonalResponse> {
    if (!this.puedeActualizar()) {
        return throwError(() => new Error('No tiene permisos para desactivar personal'));
    }

    return this.http.post<PersonalResponse>(`${this.apiUrl}/${id}/desactivar`, {}).pipe(
        tap(response => {
            console.log('📥 Respuesta desactivar:', response);
            if (response.success) {
                this.notificationService.showSuccess('Personal desactivado exitosamente');
                // ✅ IMPORTANTE: Recargar la lista para reflejar el cambio
                this.listarPersonal({}).subscribe();
            }
        }),
        catchError(this.handleError)
    );
}

getPersonalDisponible(): Observable<any> {
  return this.http.get(`${this.apiUrl}/disponible`).pipe(
    catchError(this.handleError)
  );
}

  /**
   * Cambiar estado (alternativa unificada)
   */
  cambiarEstadoPersonal(id: number, activo: boolean): Observable<PersonalResponse> {
    return activo ? this.activarPersonal(id) : this.desactivarPersonal(id);
  }

  /**
   * Obtener personal activo
   * GET /api/v1/personal/activos (si existe este endpoint)
   */
  listarPersonalActivo(): Observable<PersonalListResponse> {
   return this.http.get<PersonalListResponse>(`${this.apiUrl}/activos`).pipe(
        tap(response => console.log('📥 Personal activos:', response)),
        catchError(this.handleError)
    );
  }

  /**
   * Obtener personal del usuario actual
   */
  obtenerPersonalActual(): Observable<PersonalResponse> {
    const user = this.authService.getCurrentUser();
    if (!user?.personal_id) {
      return throwError(() => new Error('Usuario no tiene personal asociado'));
    }
    return this.obtenerPersonal(user.personal_id);
  }

  // ========== MÉTODOS DE APOYO ==========

  private handleError(error: any): Observable<never> {
    console.error('❌ Error en PersonalService:', error);

    let errorMessage = 'Error desconocido';

    if (error.error instanceof ErrorEvent) {
      errorMessage = `Error del cliente: ${error.error.message}`;
    } else {
      switch (error.status) {
        case 401:
          errorMessage = 'No autorizado';
          break;
        case 403:
          errorMessage = 'No tiene permisos para esta acción';
          break;
        case 404:
          errorMessage = 'Recurso no encontrado';
          break;
        case 422:
          errorMessage = 'Error de validación';
          if (error.error?.errors) {
            const errors = error.error.errors;
            errorMessage = Object.values(errors).flat().join(', ');
          } else if (error.error?.message) {
            errorMessage = error.error.message;
          }
          break;
        case 500:
          errorMessage = 'Error interno del servidor';
          break;
        default:
          errorMessage = error.error?.message || `Error ${error.status}`;
      }
    }

    if (this.notificationService) {
        this.notificationService.showError(errorMessage);
    } else {
        console.error('NotificationService no disponible:', errorMessage);
    }
    return throwError(() => new Error(errorMessage));
  }

  // ========== VALIDACIONES ==========

  validarDatosCreacion(datos: CreatePersonalDTO): string[] {
    const errores: string[] = [];

    if (!datos.persona_id) {
      errores.push('La persona es requerida');
    }

    if (!datos.cargo_id) {
      errores.push('El cargo es requerido');
    }

    if (!datos.fecha_ingreso) {
      errores.push('La fecha de ingreso es requerida');
    } else {
      // Validar que no sea fecha futura
      const fechaIngreso = new Date(datos.fecha_ingreso);
      const hoy = new Date();
      hoy.setHours(0, 0, 0, 0);

      if (fechaIngreso > hoy) {
        errores.push('La fecha de ingreso no puede ser futura');
      }
    }

    if (datos.fecha_egreso && datos.fecha_ingreso) {
      const egreso = new Date(datos.fecha_egreso);
      const ingreso = new Date(datos.fecha_ingreso);

      if (egreso < ingreso) {
        errores.push('La fecha de egreso no puede ser anterior a la fecha de ingreso');
      }
    }

    return errores;
  }

 /**
 * Crear personal
 * POST /api/v1/personal
 */
crearPersonal(datos: CreatePersonalDTO): Observable<PersonalResponse> {
  if (!this.puedeCrear()) {
    this.notificationService.showError('No tiene permisos para crear personal');
    return throwError(() => new Error('No tiene permisos para crear personal'));
  }

  // ✅ ASEGURAR QUE activo sea booleano, no número
  const datosCorregidos = {
    ...datos,
    activo: datos.activo ?? true,
    fecha_ingreso: datos.fecha_ingreso?.includes('T')
      ? datos.fecha_ingreso.split('T')[0]
      : datos.fecha_ingreso
  };

  // Agregar usuario_creacion_id del usuario actual
  const user = this.authService.getCurrentUser();
  if (user) {
    datosCorregidos.usuario_creacion_id = user.usuario_id;
  }

  console.log('📤 Creando personal:', datosCorregidos);

  return this.http.post<PersonalResponse>(this.apiUrl, datosCorregidos).pipe(
    tap(response => {
      console.log('📥 Respuesta creación:', response);
      if (response.success) {
        this.notificationService.showSuccess(response.message || 'Personal creado exitosamente');
      }
    }),
    catchError(this.handleError)
  );
}

// ========== MÉTODOS DE EXPORTACIÓN ==========

/**
 * Exportar listado completo a Excel
 */
exportarExcel(): Observable<Blob> {
  return this.http.get(`${this.apiUrl}/exportar-excel`, {
    responseType: 'blob'
  }).pipe(
    catchError(this.handleError)
  );
}

/**
 * Exportar reporte específico a PDF
 */
exportarReportePDF(tipo: string): Observable<Blob> {
  return this.http.get(`${this.apiUrl}/reportes/${tipo}/pdf`, {
    responseType: 'blob'
  }).pipe(
    catchError(this.handleError)
  );
}

/**
 * Exportar reporte específico a Excel
 */
exportarReporteExcel(tipo: string): Observable<Blob> {
  return this.http.get(`${this.apiUrl}/reportes/${tipo}/excel`, {
    responseType: 'blob'
  }).pipe(
    catchError(this.handleError)
  );
}

/**
 * Exportar reporte completo (todos los reportes en uno)
 */
exportarReporteCompleto(): Observable<Blob> {
  return this.http.get(`${this.apiUrl}/reportes/completo/pdf`, {
    responseType: 'blob'
  }).pipe(
    catchError(this.handleError)
  );
}

/**
 * Generar contrato PDF para un empleado
 * GET /api/v1/personal/{id}/contrato-pdf
 */
generarContratoPDF(id: number): Observable<Blob> {
  return this.http.get(`${this.apiUrl}/${id}/contrato-pdf`, {
    responseType: 'blob'
  }).pipe(
    tap(blob => {
      // Crear link de descarga
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `contrato_personal_${id}.pdf`;
      link.click();
      window.URL.revokeObjectURL(url);

      // La notificación se maneja en el componente
    }),
    catchError(this.handleError)
  );
}

}
