import { Injectable } from '@angular/core';
import { INotification } from '../../interfaces/notification.interface';

@Injectable({ providedIn: 'root' })
export class NotificationStorageService {
  private readonly STORAGE_KEY = 'app_notifications';
  private readonly MAX_STORAGE = 100;

  saveNotifications(notifications: INotification[]): void {
    const toStore = notifications.slice(0, this.MAX_STORAGE);
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(toStore));
  }

  loadNotifications(): INotification[] {
    const stored = localStorage.getItem(this.STORAGE_KEY);
    if (!stored) return [];

    try {
      return JSON.parse(stored);
    } catch {
      return [];
    }
  }

  clearNotifications(): void {
    localStorage.removeItem(this.STORAGE_KEY);
  }

  getStoredCount(): number {
    return this.loadNotifications().length;
  }
}
