import { Routes } from '@angular/router';
import { LoginComponent } from '../app/shared/features/login/login.component';
import { SecurityQuestionsComponent } from '../app/shared/features/security-questions/security-questions.component';
import { ConfigureSecurityComponent } from './shared/features/configure-questions/configure-security.component';
import { securityGuard } from './core/guards/security.guard';
import { ModuleResolver } from './core/resolvers/module.resolver';

export const routes: Routes = [
  {
     path: '',
    pathMatch: 'full',
    redirectTo: 'home'
  },
  {
    path: 'home',
    loadComponent: () => import('./shared/features/home/home.component')
      .then(m => m.HomeComponent),

  },
  {
    path: 'login',
    component: LoginComponent
  },
    {
    path: 'forgot-password',
     loadComponent: () => import('./shared/features/reset-password/forgot-password.component')
      .then(m => m.ForgotPasswordComponent),

    },
  {
    path: 'reset-password',
    loadComponent: () => import('./shared/features/reset-password/reset-password.component')
      .then(m => m.ResetPasswordComponent),
  },
  {
    path: 'configure-security',
    component: ConfigureSecurityComponent,
    canActivate: [securityGuard]
  },
  {
    path: 'security-questions',
    component: SecurityQuestionsComponent,
    canActivate: [securityGuard]
  },
  {
    path: '',
    canActivate: [securityGuard], // TODAS las rutas hijas requieren seguridad
    children: [
      {
        path: 'dashboard',
        loadComponent: () => import('./modules/dashboard/dashboard.component')
          .then(m => m.DashboardComponent),
           resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Dashboard'
      },
      {
        path: 'denuncias',
        loadComponent: () => import('./modules/denuncias/pages/denuncias-list/denuncias-list.component')
          .then(m => m.DenunciasListComponent),
          resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Denuncias'
      },
      {
        path: 'catalogos',
        loadComponent: () => import('./modules/catalogos/pages/catalogos-list/catalogos.component')
          .then(m => m.CatalogosComponent),
          resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Normativas'
      },
      {
        path: 'personas',
        loadComponent: () => import('./modules/personas/pages/personas.component')
          .then(m => m.PersonasListComponent),
          resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Personas'
      },
      {
        path: 'intermediaciones',
        loadComponent: () => import('./modules/intermediaciones/pages/intermediacion.component')
          .then(m => m.RemisionConciliacionComponent),
            resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Intermediaciones'
      },
      {
        path: 'resoluciones',
        loadComponent: () => import('./modules/resoluciones/pages/resolucion.component')
          .then(m => m.MedidaSentenciaComponent),
            resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Resoluciones'
      },
      {
        path: 'expedientes',
        loadComponent: () => import('./modules/expedientes/pages/expediente.component')
          .then(m => m.ExpedienteComponent),
            resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Expedientes'
      },
      {
        path: 'personal',
        loadComponent: () => import('./modules/personal/pages/personal.component')
          .then(m => m.PersonalListComponent),
            resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Personal'
      },
      {
        path: 'calendario',
        loadComponent: () => import('./modules/calendario/pages/calendario.component').then(m => m.CalendarioComponent),
          resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Calendario'
      },
      {
        path: 'reportes',
        loadComponent: () => import('./modules/reportes/pages/reportes.component')
          .then(m => m.ReportesNotificacionesComponent),
            resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Reportes'
      },
      {
        path: 'seguridad',
          children: [
            {
              path: 'usuarios',
              loadComponent: () => import('./modules/seguridad/pages/usuarios/usuarios.component')
                .then(m => m.UsuariosComponent),
                  resolve: { module: ModuleResolver },
              title: 'SIGPAZ │ Usuarios'
            },
            {
              path: 'accesos',
              loadComponent: () => import('./modules/seguridad/pages/accesos/acceso.component')
                .then(m => m.AccesosComponent),
                  resolve: { module: ModuleResolver },
              title: 'SIGPAZ │ Accesos'
            },
            {
              path: 'auditorias',
              loadComponent: () => import('./modules/seguridad/pages/auditorias/auditoria.component')
                .then(m => m.AuditoriaComponent),
                resolve: { module: ModuleResolver },
                 data: { permission: 'auditoria.ver', title: 'Auditoría del Sistema' },
              title: 'SIGPAZ │ Auditorias'
            }
          ]
      },
      {
        path: 'backup',
        loadComponent: () => import('./modules/backup-restore/backup-restore.component')
          .then(m => m.BackupRestoreComponent),
          resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Backup and Restore'
      },
      {
        path: 'manuales',
        children: [
          {
            path: 'usuario',
            loadComponent: () => import('./modules/manuales/pages/manual-usuario/manual-usuario.component')
              .then(m => m.ManualUsuarioComponent),
              resolve: { module: ModuleResolver },
            title: 'SIGPAZ │ Manual de Usuario'
          },
          {
            path: 'tecnico',
            loadComponent: () => import('./modules/manuales/pages/manual-tecnico/manual-tecnico.component')
              .then(m => m.ManualTecnicoComponent),
              resolve: { module: ModuleResolver },
            title: 'SIGPAZ │ Manual Técnico'
          }
        ]
      },
      {
        path: 'audiovisual',
        loadComponent: () => import('./modules/audiovisual/pages/audiovisual.component')
          .then(m => m.AudiovisualComponent),
          resolve: { module: ModuleResolver },
        title: 'SIGPAZ │ Audiovisual'
      },
      {
        path: '**',
        loadComponent: () => import('./modules/not-found/not-found.component')
          .then(m => m.NotFoundComponent)
      }
    ]
  }
];
