import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

export interface ModalState {
  otpModal: boolean;
  codigoMaestroModal: boolean;
  sessionTimeoutModal: boolean;
  loadingModal: boolean;
}

@Injectable({ providedIn: 'root' })
export class ModalService {
  private modalState = new BehaviorSubject<ModalState>({
    otpModal: false,
    codigoMaestroModal: false,
    sessionTimeoutModal: false,
    loadingModal: false
  });

  modalState$: Observable<ModalState> = this.modalState.asObservable();

  // Cerrar todos los modales
  closeAllModals(): void {
    console.log('🔒 Cerrando todos los modales');
    this.modalState.next({
      otpModal: false,
      codigoMaestroModal: false,
      sessionTimeoutModal: false,
      loadingModal: false
    });
  }

  // Cerrar modales específicos
  closeModal(modalName: keyof ModalState): void {
    const current = this.modalState.value;
    this.modalState.next({
      ...current,
      [modalName]: false
    });
  }

  // Abrir modal específico
  openModal(modalName: keyof ModalState): void {
    const current = this.modalState.value;
    this.modalState.next({
      ...current,
      [modalName]: true
    });
  }

  // Actualizar estado individual
  updateModal(modalName: keyof ModalState, value: boolean): void {
    const current = this.modalState.value;
    this.modalState.next({
      ...current,
      [modalName]: value
    });
  }

  getCurrentState(): ModalState {
    return this.modalState.value;
  }
}
