import { Component, OnInit, OnDestroy, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Subscription } from 'rxjs';
import { NotificationService } from '../../../core/services/notification/notification.service';
import { DialogService } from '../../../core/services/dialog/dialog.service';
import { RelativeTimePipe } from '../../pipes/relative-time.pipe';
import { INotification } from '../../../core/interfaces/notification.interface';

@Component({
  selector: 'app-notification',
  standalone: true,
  imports: [CommonModule, RelativeTimePipe],
  templateUrl: './notification.component.html',
  styleUrls: ['./notification.component.less'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class NotificationComponent implements OnInit, OnDestroy {
  isOpen = false;
  notifications: INotification[] = [];
  unreadCount = 0;
  loading = false;

  private subscriptions = new Subscription();

  constructor(
    private notificationService: NotificationService,
    private dialogService: DialogService,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
     this.subscriptions.add(
    this.notificationService.state$.subscribe((state) => {
      this.notifications = state.notifications;
      this.unreadCount = state.unreadCount;
      this.loading = state.loading;
      this.cdr.markForCheck();
    })
  );

    this.subscriptions.add(
      this.notificationService.unreadCount$.subscribe((count: number) => {
        this.unreadCount = count;
        this.cdr.markForCheck();
      })
    );

    this.subscriptions.add(
      this.notificationService.loading$.subscribe((loading: boolean) => {
        this.loading = loading;
        this.cdr.markForCheck();
      })
    );
  }

  toggleDropdown(): void {
    this.isOpen = !this.isOpen;
    if (this.isOpen) {
      this.setupClickOutsideListener();
    } else {
      this.removeClickOutsideListener();
    }
  }

  markAllAsRead(): void {
    this.notificationService.markAllAsRead().subscribe({
      error: (error: any) => console.error('Error marking all as read:', error)
    });
  }

 deleteAll(): void {
  this.dialogService.confirm({
    title: 'Confirmar eliminación',
    message: '¿Está seguro de eliminar TODAS las notificaciones? Esta acción no se puede deshacer.',
    confirmText: 'Eliminar todo',
    type: 'danger',
    onConfirm: () => {
      // Mostrar estado de carga
      this.loading = true;
      this.cdr.markForCheck();

      this.notificationService.deleteAll().subscribe({
        next: () => {
          this.loading = false;
          this.cdr.markForCheck();
          // Opcional: cerrar el dropdown después de eliminar
          setTimeout(() => {
            this.isOpen = false;
            this.cdr.markForCheck();
          }, 1500);
        },
        error: (error) => {
          console.error('Error en deleteAll:', error);
          this.loading = false;
          this.cdr.markForCheck();
        }
      });
    }
  });
}

  onNotificationClick(notification: INotification): void {
    if (!notification.read) {
      this.notificationService.markAsRead(notification.id).subscribe();
    }

    if (notification.actionUrl) {
      // Navegar a la URL - puedes implementar router navigation
      // this.router.navigateByUrl(notification.actionUrl);
    }
  }

  getAvatarColor(module?: string): string {
    const colors: Record<string, string> = {
      personas: '#4CAF50',
      denuncias: '#FF9800',
      reportes: '#2196F3',
      usuarios: '#9C27B0',
      sistema: '#607D8B',
      backup: '#795548',
      configuracion: '#3F51B5'
    };
    return colors[module || 'sistema'] || '#3F51B5';
  }

  getDefaultAvatar(type: string): string {
    const avatars: Record<string, string> = {
      success: '✅',
      error: '❌',
      warning: '⚠️',
      info: 'ℹ️'
    };
    return avatars[type] || '📢';
  }

  trackByFn(index: number, notification: INotification): number {
    return notification.id;
  }

  private clickOutsideHandler?: (event: MouseEvent) => void;

  private setupClickOutsideListener(): void {
    setTimeout(() => {
      this.clickOutsideHandler = (event: MouseEvent) => {
        const target = event.target as HTMLElement;
        const wrapper = document.querySelector('.notification-wrapper');
        if (wrapper && !wrapper.contains(target)) {
          this.isOpen = false;
          this.removeClickOutsideListener();
          this.cdr.markForCheck();
        }
      };
      document.addEventListener('click', this.clickOutsideHandler);
    });
  }

  private removeClickOutsideListener(): void {
    if (this.clickOutsideHandler) {
      document.removeEventListener('click', this.clickOutsideHandler);
      this.clickOutsideHandler = undefined;
    }
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
    this.removeClickOutsideListener();
  }
}
