// core/services/theme.service.ts
import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

export type ThemeType = 'light' | 'dark' | 'neon';

@Injectable({
  providedIn: 'root'
})
export class ThemeService {
  private themeSubject = new BehaviorSubject<ThemeType>('light');
  public theme$: Observable<ThemeType> = this.themeSubject.asObservable();

  constructor() {
    this.loadTheme();
  }

  private loadTheme(): void {
    const savedTheme = localStorage.getItem('theme') as ThemeType;
    if (savedTheme && ['light', 'dark', 'neon'].includes(savedTheme)) {
      this.setTheme(savedTheme);
    }
  }

  setTheme(theme: ThemeType): void {
    // ✅ Aplicar tema al body (global)
    document.body.classList.remove('light-theme', 'dark-theme', 'neon-theme');
    document.body.classList.add(`${theme}-theme`);

    // ✅ Guardar en localStorage
    localStorage.setItem('theme', theme);

    // ✅ Notificar a todos los suscriptores
    this.themeSubject.next(theme);

    console.log(`🎨 Tema cambiado a: ${theme}`);
  }

  getTheme(): ThemeType {
    return this.themeSubject.value;
  }

  toggleTheme(): void {
    const themes: ThemeType[] = ['light', 'dark', 'neon'];
    const currentIndex = themes.indexOf(this.getTheme());
    const nextTheme = themes[(currentIndex + 1) % themes.length];
    this.setTheme(nextTheme);
  }
}
