import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { finalize } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class LoadingService {
  private loadingSubject = new BehaviorSubject<boolean>(false);
  public loading$: Observable<boolean> = this.loadingSubject.asObservable();

  private messageSubject = new BehaviorSubject<string>('Cargando sistema...');
  public message$: Observable<string> = this.messageSubject.asObservable();

  private currentModuleSubject = new BehaviorSubject<string>('');
  public currentModule$: Observable<string> = this.currentModuleSubject.asObservable();

  private loadingCount = 0;
  private autoResetTimer: any = null;

  show(message?: string, moduleName?: string): void {
    // Limpiar timer de auto-reset si existe
    if (this.autoResetTimer) {
      clearTimeout(this.autoResetTimer);
      this.autoResetTimer = null;
    }

    this.loadingCount++;
    console.log(`🟢 LOADING SHOW: ${message || 'Sin mensaje'} (contador: ${this.loadingCount})`);

    if (message) {
      this.messageSubject.next(message);
    }
    if (moduleName) {
      this.currentModuleSubject.next(moduleName);
    }
    this.loadingSubject.next(true);
  }

  hide(): void {
    this.loadingCount--;
    console.log(`🔴 LOADING HIDE (contador: ${this.loadingCount})`);

    if (this.loadingCount <= 0) {
      this.loadingCount = 0;
      this.executeHide();
    }
  }

  hideAll(): void {
    console.log(`🛑 HIDE ALL - Ocultando loading inmediatamente`);
    this.loadingCount = 0;
    this.executeHide();
  }

  private executeHide(): void {
    this.loadingSubject.next(false);
    this.messageSubject.next('Cargando sistema...');
    this.currentModuleSubject.next('');

    // Auto-reset de seguridad después de 8 segundos para dar tiempo a que el loading se oculte correctamente
    if (this.autoResetTimer) {
      clearTimeout(this.autoResetTimer);
    }
    this.autoResetTimer = setTimeout(() => {
      if (this.loadingSubject.value === true) {
        console.warn(`⚠️ Auto-reset: Forzando ocultación después de timeout`);
        this.loadingSubject.next(false);
        this.loadingCount = 0;
      }
      this.autoResetTimer = null;
    }, 8000);
  }

  forceHide(): void {
    console.log(`⚠️ FORCE HIDE - Ocultando loading inmediatamente`);
    this.loadingCount = 0;
    this.executeHide();
  }

  isVisible(): boolean {
    return this.loadingSubject.value;
  }

  reset(): void {
    console.log(`🔄 Reset completo del loading service`);
    this.loadingCount = 0;
    this.executeHide();
  }

  wrap<T>(obs: Observable<T>, message?: string, moduleName?: string): Observable<T> {
    this.show(message, moduleName);
    return obs.pipe(finalize(() => this.hide()));
  }
}
